def render_test_snippet(test_name: str, line_number: int) -> list[str]:
    with open(test_name, "r", encoding="utf8", errors="backslashreplace") as f:
        file_lines = f.read().splitlines()
    if not file_lines:
        return []

    target_idx = max(0, min(line_number - 1, len(file_lines) - 1))

    # Expand the window outward until we hit a blank line (or a file boundary)
    # on either side of the target line.
    start = target_idx
    while start > 0 and file_lines[start - 1].strip() != "":
        start -= 1
    end = target_idx
    while end < len(file_lines) - 1 and file_lines[end + 1].strip() != "":
        end += 1

    window = list(range(start, end + 1))
    while window and file_lines[window[0]].strip() == "":
        window.pop(0)
    while window and file_lines[window[-1]].strip() == "":
        window.pop()
    if not window:
        return []

    width = len(str(window[-1] + 1))
    rendered = []
    for idx in window:
        number = str(idx + 1).rjust(width)
        content = file_lines[idx]
        if idx == target_idx:
            rendered.append(f"  > {number}  {content}")
        else:
            rendered.append(f"    {number}  {content}")
    return rendered


def parse_progress_starts(output: str):
    # Progress lines for tests that started but did not report a "took" suffix.
    starts = []
    for line in strip_ansi(output).splitlines():
        stripped = line.strip()
        if TEST_RUNTIME_PATTERN.match(stripped):
            continue
        match = PROGRESS_START_PATTERN.match(stripped)
        if match:
            starts.append(match.group(1).strip())
    return starts


def has_progress_info(output: str):
    for line in strip_ansi(output).splitlines():
        if PROGRESS_START_PATTERN.match(line.strip()):
            return True
    return False


def identify_timed_out_test(stdout: str, batch: list):
    if not batch:
        return None
    if has_progress_info(stdout):
        completed = {name for name, _ in parse_test_runtimes(stdout)}
        for test in batch:
            if test not in completed:
                return test
    return batch[-1]


def find_structured_block(stderr: str):
    lines = stderr.splitlines()
    for idx, line in enumerate(lines):
        match = STRUCTURED_HEADER_PATTERN.match(line)
        if match:
            end = len(lines)
            for trailer_idx in range(idx + 1, len(lines)):
                if lines[trailer_idx].lstrip().startswith("~~~"):
                    end = trailer_idx
                    break
            return {
                "path": match.group(1).strip(),
                "line_number": int(match.group(2)),
                "block": lines[idx:end],
            }
    return None


def extract_failed_path(stdout: str):
    fallback = None
    for line in stdout.splitlines():
        match = FAILED_LINE_PATTERN.match(line.strip())
        if match:
            path = match.group(1).strip()
            if path.endswith((".test", ".test_slow")):
                return path
            if fallback is None:
                fallback = path
    return fallback


def _trim_blank_edges(lines: list) -> list:
    trimmed = list(lines)
    while trimmed and trimmed[0].strip() == "":
        trimmed.pop(0)
    while trimmed and trimmed[-1].strip() == "":
        trimmed.pop()
    return trimmed


def _summarize_timeout(message: str, stdout: str, batch: list):
    match = TIMEOUT_MESSAGE_PATTERN.match(message.strip())
    seconds = float(match.group(1))
    seconds_str = str(int(seconds)) if seconds.is_integer() else str(seconds)
    test_name = identify_timed_out_test(stdout, batch)
    lines = [f"error: timeout ({seconds_str}s) for {test_name}."]
    return lines, [test_name] if test_name is not None else []


def _summarize_wrong_result(structured: dict):
    path = structured["path"]
    block = structured["block"]
    expected = ""
    actual = ""
    description = ""
    for idx, line in enumerate(block):
        stripped = line.strip()
        if stripped.startswith("Mismatch on row"):
            description = stripped
            for value_line in block[idx + 1 :]:
                value_stripped = value_line.strip()
                if not value_stripped:
                    continue
                value_match = MISMATCH_VALUE_PATTERN.match(value_stripped)
                if value_match:
                    actual = value_match.group(1).strip()
                    expected = value_match.group(2).strip()
                break
            break
    summary = f"expected: {expected}, got {actual}; {description}"
    lines = [f"error: FAIL {path}", "", summary, ""]
    try:
        lines.extend(render_test_snippet(path, structured["line_number"]))
    except OSError:
        pass
    return lines, [path]


def _summarize_generic_structured(structured: dict):
    path = structured["path"]
    content = _trim_blank_edges(structured["block"])
    lines = [f"error: FAIL {path}", ""] + content
    return lines, [path]


def _summarize_signal(stdout: str, batch: list):
    lines = stdout.splitlines()
    signal_name = ""
    for idx, line in enumerate(lines):
        if "fatal error condition" in line:
            for following in lines[idx + 1 :]:
                if following.strip():
                    signal_name = following.strip()
                    break
            break
    starts = parse_progress_starts(stdout)
    test_name = starts[-1] if starts else (batch[-1] if batch else None)
    out = [f"error: FAIL {test_name}", "", signal_name]
    return out, [test_name] if test_name is not None else []


def _summarize_explicit_message(stdout: str, batch: list):
    lines = stdout.splitlines()
    message_lines = []
    for idx, line in enumerate(lines):
        if "explicitly with message:" in line:
            for following in lines[idx + 1 :]:
                stripped = following.strip()
                if not stripped or stripped.startswith("~~~") or set(stripped) <= {"=", "-"}:
                    break
                message_lines.append(stripped)
            break
    starts = parse_progress_starts(stdout)
    path = extract_failed_path(stdout) or (starts[-1] if starts else (batch[-1] if batch else None))
    out = [f"error: FAIL {path}", ""] + message_lines
    return out, [path] if path is not None else []


def _summarize_fallback(stdout: str, stderr: str, batch: list):
    starts = parse_progress_starts(stdout)
    test_name = starts[-1] if starts else (batch[-1] if batch else None)
    body = _trim_blank_edges((stdout.strip() + "\n" + stderr.strip()).strip().splitlines())
    out = [f"error: FAIL {test_name}"]
    if body:
        out.append("")
        out.extend(body)
    return out, [test_name] if test_name is not None else []


def summarize_failure_output(message: str | None, stdout: str, stderr: str, batch: list):
    stdout = strip_ansi(normalize_output(stdout))
    stderr = strip_ansi(normalize_output(stderr))

    if message and TIMEOUT_MESSAGE_PATTERN.match(message.strip()):
        return _summarize_timeout(message, stdout, batch)

    structured = find_structured_block(stderr)
    if structured is not None:
        if any("Wrong result in query!" in line for line in structured["block"]):
            return _summarize_wrong_result(structured)
        return _summarize_generic_structured(structured)

